INSERT INTO products (id,title,author,description,image,isbn,publisher,published_year,language,created_at,updated_at,category_id) VALUES (1,'Miền ký ức xanh','An Nhiên','Những câu chuyện đời thường được kể bằng giọng văn ấm áp, đưa người đọc qua ký ức, tình bạn và những điều nhỏ bé đáng trân trọng. Hợp với một chiều yên tĩnh bên tách trà. Tác phẩm và thông tin xuất bản thuộc bộ dữ liệu minh họa của Góc Sách.','',NULL,'Tủ sách Góc · Minh họa',2020,'Tiếng Việt','2026-09-03T00:00:00Z','2026-10-02T10:23:40.095375200Z',1);
INSERT INTO products (id,title,author,description,image,isbn,publisher,published_year,language,created_at,updated_at,category_id) VALUES (2,'Những ngày có nắng','Minh Thư','Một khoảng nghỉ dịu dàng giữa nhịp sống bận rộn. Từng chương ngắn gợi mở cách quan sát, chăm sóc bản thân và giữ lại những điều có ý nghĩa trong mỗi ngày. Tác phẩm và thông tin xuất bản thuộc bộ dữ liệu minh họa của Góc Sách.','',NULL,'Tủ sách Góc · Minh họa',2021,'Tiếng Việt','2026-09-03T00:00:00Z','2026-10-03T10:23:40.095375200Z',2);
INSERT INTO products (id,title,author,description,image,isbn,publisher,published_year,language,created_at,updated_at,category_id) VALUES (3,'Lập trình từ trang đầu','Hoàng Nam','Khởi đầu từ những câu hỏi gần gũi, cuốn sách đưa người đọc đến với tư duy hệ thống, sáng tạo và công nghệ. Các ví dụ giúp biến ý tưởng thành điều có thể thực hành. Tác phẩm và thông tin xuất bản thuộc bộ dữ liệu minh họa của Góc Sách.','',NULL,'Tủ sách Góc · Minh họa',2022,'Tiếng Việt','2026-09-03T00:00:00Z','2026-10-04T10:23:40.095375200Z',3);
