INSERT INTO reviews (id,user_id,product_id,order_id,rating,media_url,media_type,body,status,created_at,updated_at) VALUES (1,3,24,1,5,'','','Sách được đóng gói cẩn thận, tình trạng đúng mô tả. Mình thích cách các chương ngắn gợi mở một thói quen đọc mỗi ngày, rất dễ bắt đầu lại sau thời gian bận rộn.','PUBLISHED','2026-10-24T10:23:40.310791700Z','2026-10-24T10:23:40.310791700Z');
INSERT INTO reviews (id,user_id,product_id,order_id,rating,media_url,media_type,body,status,created_at,updated_at) VALUES (2,5,24,6,4,'','','Một cuốn sách nhẹ nhàng, phù hợp để đọc vào buổi tối. Bản mình nhận gần như mới, cửa hàng mô tả rõ tình trạng nên chọn mua sách cũ cũng rất yên tâm.','PUBLISHED','2026-10-22T10:23:40.312890100Z','2026-10-22T10:23:40.312890100Z');
INSERT INTO reviews (id,user_id,product_id,order_id,rating,media_url,media_type,body,status,created_at,updated_at) VALUES (3,5,23,6,5,'','','Những câu chuyện nhỏ nhưng để lại nhiều cảm xúc. Giấy sách còn đẹp và không thiếu trang. Mình đã đánh dấu vài đoạn muốn đọc lại cùng bạn bè vào cuối tuần.','PUBLISHED','2026-10-22T10:23:40.312890100Z','2026-10-22T10:23:40.312890100Z');
